<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\{HttpException,Request};
use Sentinel\Services\{WebhookTransport,SafeWebhookTransport};
use Sentinel\Tests\FieldFixture;
final class OperationsHubTest extends TestCase
{
    private function fixture():array {[$app,$db,$ctx]=FieldFixture::create();$transport=new class implements WebhookTransport {public array $sent=[];public array $result=['state'=>'ACCEPTED','status'=>204,'result'=>'Fixture accepted.'];public function send(string $url,string $body,array $headers):array {$this->sent[]=compact('url','body','headers');return $this->result;}};$app->container()->instance('webhook_transport',$transport);return [$app,$db,$ctx,$transport];}
    private function rejects(callable $fn,int $status):void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
    private function radio($app):array {$r=$app->container()->make('radio_service');$id=$r->create(['site_id'=>1,'channel_name'=>'Site team','history_enabled'=>false])['id'];foreach([1,2]as$user)$r->member($id,['user_id'=>$user,'enabled'=>true]);return [$r,$id];}
    private function audio(string $uuid,string $lease):array {return ['operation_uuid'=>$uuid,'lease'=>$lease,'mime_type'=>'audio/webm','audio_base64'=>base64_encode("\x1a\x45\xdf\xa3".str_repeat('fixture',20))];}
    private function rule($app,$db):void {$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$app->container()->make('operational_alert_service')->rule(['site_id'=>1,'expected_revision'=>0,'recipient_user_id'=>1,'backup_user_id'=>2,'queue_minutes'=>1,'findings_hours'=>1,'escalate_minutes'=>1,'enabled'=>true]);}
    public function testVoiceFloorPriorityRetryMembershipAndExpiry():void {
        [$app,$db,$ctx]=$this->fixture();[$r,$id]=$this->radio($app);$uuid=uuid4();$first=$r->claim($id,['operation_uuid'=>$uuid,'priority'=>false]);$ctx->setUser('2');$this->rejects(fn()=>$r->claim($id,['operation_uuid'=>uuid4(),'priority'=>false]),409);$urgent=uuid4();$claim=$r->claim($id,['operation_uuid'=>$urgent,'priority'=>true]);$ctx->setUser('1');$this->rejects(fn()=>$r->send($id,$this->audio($uuid,$first['lease'])),409);$ctx->setUser('2');$message=$r->send($id,$this->audio($urgent,$claim['lease']));self::assertSame($message['id'],$r->send($id,$this->audio($urgent,$claim['lease']))['id']);self::assertCount(1,$r->feed($id,[])['messages']);$this->rejects(fn()=>$r->acknowledge('1'),403);$ctx->setUser('1');self::assertTrue($r->acknowledge('1')['acknowledged']);self::assertSame('audio/webm',$r->audio($message['id'])['mime']);$r->member($id,['user_id'=>2,'enabled'=>false]);$ctx->setUser('2');$this->rejects(fn()=>$r->audio($message['id']),404);$ctx->setUser('1');$db->execute("UPDATE radio_messages SET expires_at='2020-01-01 00:00:00'");$this->rejects(fn()=>$r->audio($message['id']),404);self::assertSame(1,$r->purgeExpired()['expired_audio_removed']);
    }
    public function testNewRadioMemberCannotReadSameSecondPriorAudio():void {
        [$app,$db,$ctx]=$this->fixture();[$r,$id]=$this->radio($app);$r->member($id,['user_id'=>2,'enabled'=>false]);$uuid=uuid4();$lease=$r->claim($id,['operation_uuid'=>$uuid,'priority'=>true]);$m=$r->send($id,$this->audio($uuid,$lease['lease']));$r->member($id,['user_id'=>2,'enabled'=>true]);$ctx->setUser('2');self::assertSame([],$r->feed($id,[])['messages']);self::assertSame([],$r->feed($id,[])['priority_calls']);$this->rejects(fn()=>$r->acknowledge('1'),404);$this->rejects(fn()=>$r->audio($m['id']),404);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$r->feed($id,[]),404);
    }
    public function testMapShowsOnlyCurrentSiteDutyAndMarksOldOrFuturePoints():void {
        [$app,$db]=$this->fixture();foreach(['latitude NUMERIC','longitude NUMERIC']as$c)$db->execute('ALTER TABLE sites ADD COLUMN '.$c);foreach(['latitude NUMERIC','longitude NUMERIC','accuracy NUMERIC','mock_location INTEGER']as$c)$db->execute('ALTER TABLE gps_locations ADD COLUMN '.$c);$db->execute('UPDATE sites SET latitude=-29.85,longitude=31.02 WHERE site_id=1');$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(1,101,2,1,:start,:end,'ASSIGNED')",['start'=>gmdate('Y-m-d H:i:s',time()-7200),'end'=>gmdate('Y-m-d H:i:s',time()+7200)]);$db->execute('INSERT INTO gps_locations VALUES(101,2,:time,-29.86,31.03,20,0),(202,3,:other,-30,30,5,0)',['time'=>gmdate('Y-m-d H:i:s',time()-600),'other'=>gmdate('Y-m-d H:i:s')]);$s=$app->container()->make('control_map_service');$map=$s->snapshot(['site_id'=>1]);self::assertCount(1,$map['guards']);self::assertSame('STALE',$map['guards'][0]['state']);$db->execute('UPDATE gps_locations SET captured_at=:time WHERE company_id=101',['time'=>gmdate('Y-m-d H:i:s',time()+600)]);$map=$s->snapshot(['site_id'=>1]);self::assertSame('INVALID_TIME',$map['guards'][0]['state']);self::assertNull($map['guards'][0]['position']);$db->execute('UPDATE gps_locations SET captured_at=:time WHERE company_id=101',['time'=>gmdate('Y-m-d H:i:s',time()-8000)]);self::assertSame('UNKNOWN',$s->snapshot(['site_id'=>1])['guards'][0]['state']);$this->rejects(fn()=>$s->snapshot(['site_id'=>3]),404);
    }
    public function testMonthlyReviewsRequirePublicationAndCurrentClientMapping():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$s=$app->container()->make('service_review_service');$id=$s->generate(['site_id'=>1,'month_code'=>gmdate('Y-m'),'summary'=>'Recorded performance reviewed.','expected_revision'=>0])['id'];$ctx->setUser('2');self::assertSame([],$s->list(['site_id'=>1],true));$ctx->setUser('1');$s->action($id,['title'=>'Review gate procedure','owner_user_id'=>1,'due_on'=>gmdate('Y-m-d')]);$s->publish($id,['expected_revision'=>1]);$this->rejects(fn()=>$s->generate(['site_id'=>1,'month_code'=>gmdate('Y-m'),'summary'=>'Rewrite published record','expected_revision'=>2]),409);$s->finishAction('1',['expected_revision'=>1,'notes'=>'Procedure reviewed.']);$ctx->setUser('2');$review=$s->list(['site_id'=>1],true)[0];$s->feedback($id,['expected_hash'=>$review['published_hash'],'rating'=>5,'comments'=>'Helpful review.']);$s->finishAction('1',['expected_revision'=>2],true);self::assertSame('CLIENT_CONFIRMED',$s->list(['site_id'=>1],true)[0]['actions'][0]['state']);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$this->rejects(fn()=>$s->list(['site_id'=>1],true),404);
    }
    public function testMapPatrolProgressDoesNotCountSkippedOrFailedCheckpoints():void {
        [$app,$db]=$this->fixture();$db->execute('INSERT INTO patrol_routes VALUES(1,101,1)');$db->execute("INSERT INTO patrol_sessions(patrol_session_id,company_id,patrol_route_id,started_at,status) VALUES(1,101,1,:now,'IN_PROGRESS')",['now'=>gmdate('Y-m-d H:i:s')]);$db->execute("INSERT INTO patrol_checkpoints VALUES(1,101,1,1,5,'ACTIVE',NULL),(2,101,1,2,5,'ACTIVE',NULL)");$db->execute("INSERT INTO patrol_checkpoint_events VALUES(101,1,1,'VISITED',:first),(101,1,2,'SKIPPED',:second),(101,1,2,'FAILED',:third)",['first'=>gmdate('Y-m-d H:i:s'),'second'=>gmdate('Y-m-d H:i:s'),'third'=>gmdate('Y-m-d H:i:s')]);$patrol=$app->container()->make('control_map_service')->snapshot(['site_id'=>1])['patrols'][0];self::assertSame(2,$patrol['checkpoint_total']);self::assertSame(1,$patrol['checkpoint_visits']);
    }
    public function testIntegrationCredentialsAreHashedScopedIdempotentAndRevocable():void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('integration_centre_service');$created=$s->createKey(['site_id'=>1,'label'=>'Alarm receiver','scopes'=>['alarms.write'],'valid_days'=>1]);$secret=$created['api_key'];self::assertNotSame($secret,$db->fetch('SELECT key_hash FROM integration_credentials')['key_hash']);self::assertStringNotContainsString($secret,json_encode($s->overview()));$body=['operation_uuid'=>uuid4(),'title'=>'Gate alarm','description'=>'External input for operator review.','severity'=>'HIGH'];$first=$s->incoming($secret,'alarms.write',$body);self::assertSame($first,$s->incoming($secret,'alarms.write',$body));self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM incidents')['n']);$this->rejects(fn()=>$s->incoming($secret,'alarms.write',[...$body,'description'=>'Changed']),409);$this->rejects(fn()=>$s->incoming($secret,'access.write',[]),401);$this->rejects(fn()=>$s->incoming($secret,'alarms.write',[...$body,'site_id'=>3]),422);self::assertSame(101,$ctx->requireTenant());self::assertSame('1',$ctx->user());$s->revoke($created['id']);$this->rejects(fn()=>$s->incoming($secret,'alarms.write',$body),401);
    }
    public function testKeyIssuerRoleRevocationAndHttpIngressAuthentication():void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('integration_centre_service');$key=$s->createKey(['site_id'=>1,'label'=>'Gate records','scopes'=>['access.write'],'valid_days'=>1])['api_key'];$body=['operation_uuid'=>uuid4(),'visitor_name'=>'Delivery','purpose'=>'Record only','direction'=>'ENTRY'];$headers=['X-Sentinel-Key'=>$key,'Content-Type'=>'application/json'];$response=$app->handle(Request::create('POST','/api/v1/connect/access',[],$headers,json_encode($body)));self::assertSame(200,$response->status());self::assertSame('PENDING',$db->fetch('SELECT authorization FROM gate_register')['authorization']);$this->rejects(fn()=>$app->handle(Request::create('POST','/api/v1/connect/access',[],['Content-Type'=>'application/json'],json_encode($body))),401);$db->execute("DELETE FROM role_permissions WHERE role_id=1 AND permission_id IN (SELECT permission_id FROM permissions WHERE company_id=101 AND permission_code='integrations.manage')");$this->rejects(fn()=>$s->incoming($key,'access.write',$body),401);
    }
    public function testAttendanceIntegrationLabelsApprovalsAndFlagsLaterEdits():void {
        [$app,$db]=$this->fixture();$date=gmdate('Y-m-d');$db->execute('INSERT INTO attendance VALUES(1,101,1,1,:date,:start,:end,NULL,NULL)',['date'=>$date,'start'=>$date.' 08:00:00','end'=>$date.' 10:00:00']);$s=$app->container()->make('integration_centre_service');$key=$s->createKey(['site_id'=>1,'label'=>'Attendance export','scopes'=>['exports.read'],'valid_days'=>1])['api_key'];$range=['date_from'=>$date,'date_to'=>$date];self::assertSame('UNAPPROVED',$s->incoming($key,'exports.read',$range)['attendance'][0]['approval_state']);$app->container()->make('field_operations_service')->approveAttendance('1');$approved=$s->incoming($key,'exports.read',$range)['attendance'][0];self::assertSame('CURRENT',$approved['approval_state']);self::assertSame(7200,$approved['approved_worked_seconds']);$db->execute('UPDATE attendance SET clock_out_at=:end WHERE attendance_id=1',['end'=>$date.' 11:00:00']);$stale=$s->incoming($key,'exports.read',$range)['attendance'][0];self::assertSame('STALE',$stale['approval_state']);self::assertNull($stale['approved_worked_seconds']);
    }
    public function testSignedWebhooksPersistUncertainOutcomesAndRetrySameEvent():void {
        [$app,$db,$ctx,$transport]=$this->fixture();$s=$app->container()->make('integration_centre_service');$w=$s->webhook(['site_id'=>1,'label'=>'Customer receiver','endpoint_url'=>'https://receiver.example/events']);self::assertStringNotContainsString($w['signing_secret'],json_encode($s->overview()));$event=$s->event('1','fixture.created',['record_id'=>'123']);$transport->result=['state'=>'UNCERTAIN','status'=>null,'result'=>'Fixture lost response.'];$s->deliver();self::assertSame('UNCERTAIN',$s->overview()['deliveries'][0]['state']);$s->deliver();self::assertCount(1,$transport->sent);$sent=$transport->sent[0];$stamp=substr(array_values(array_filter($sent['headers'],fn($h)=>str_starts_with($h,'X-Sentinel-Timestamp: ')))[0],22);$signature='X-Sentinel-Signature: sha256='.hash_hmac('sha256',$stamp.'.'.$sent['body'],$w['signing_secret']);self::assertContains($signature,$sent['headers']);$s->retry('1',['reason'=>'Receiver confirmed safe to retry stable event.']);$transport->result=['state'=>'ACCEPTED','status'=>204,'result'=>'Received'];$s->deliver();self::assertSame('ACCEPTED',$s->overview()['deliveries'][0]['state']);self::assertSame($event['event_id'],json_decode($transport->sent[1]['body'],true)['event_id']);self::assertSame($transport->sent[0]['body'],$transport->sent[1]['body']);
    }
    public function testWebhookUrlValidationRejectsPrivateAndCredentialUrls():void {
        foreach(['http://example.com','https://127.0.0.1/a','https://localhost/a','https://service.local/a','https://user:pass@example.com/a','https://example.com:8443/a','https://example.com/a?key=secret']as$url){try{SafeWebhookTransport::validateUrl($url);self::fail('Expected unsafe URL rejection');}catch(\InvalidArgumentException){self::assertTrue(true);}}self::assertSame('receiver.example',SafeWebhookTransport::validateUrl('https://receiver.example/events'));
    }
    public function testSiteClientReassignmentStopsOldKeysAndWebhookDelivery():void {
        [$app,$db,$ctx,$transport]=$this->fixture();$s=$app->container()->make('integration_centre_service');$key=$s->createKey(['site_id'=>1,'label'=>'Original client','scopes'=>['alarms.write'],'valid_days'=>1])['api_key'];$s->webhook(['site_id'=>1,'label'=>'Original receiver','endpoint_url'=>'https://receiver.example/events']);$s->event('1','fixture.created',['id'=>'1']);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$this->rejects(fn()=>$s->incoming($key,'alarms.write',['operation_uuid'=>uuid4(),'title'=>'Old key','description'=>'Do not accept','severity'=>'LOW']),401);$s->deliver();self::assertSame([],$transport->sent);self::assertSame('CANCELLED',$s->overview()['deliveries'][0]['state']);$s->event('1','fixture.changed',['id'=>'2']);self::assertCount(1,$s->overview()['deliveries']);
    }
    public function testSupportOwnerControlsConsentAndClientCannotSeeAnotherTicket():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');$s=$app->container()->make('customer_support_service');$ctx->setUser('2');$id=$s->create(['site_id'=>1,'subject'=>'Phone sync issue','description'=>'Please help with uploads.','priority'=>'NORMAL'],true)['id'];$this->rejects(fn()=>$s->share($id,['consent'=>false]),422);$c=$s->share($id,['consent'=>true])['id'];$data=$s->diagnostic($c,true);self::assertStringNotContainsString('fixture-secret',json_encode($data));$ctx->setUser('1');$this->rejects(fn()=>$s->share($id,['consent'=>true]),404);$s->action($id,'resolve',['expected_revision'=>1,'message'=>'Reviewed diagnostics.']);$ctx->setUser('2');$s->action($id,'confirm',['expected_revision'=>2,'message'=>'Working now.'],true);$s->revoke($c);$this->rejects(fn()=>$s->diagnostic($c,true),404);$ctx->setUser('1');$this->rejects(fn()=>$s->diagnostic($c),404);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');self::assertSame([],$s->list(['site_id'=>1]));
    }
    public function testSelfSupportRequiresDutyGrantOrMappedClient():void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('customer_support_service');$ctx->setUser('2');$body=['site_id'=>1,'subject'=>'Help','description'=>'Need assistance.','priority'=>'NORMAL'];$this->rejects(fn()=>$s->create($body,true),404);$ctx->setUser('1');$app->container()->make('site_access_service')->grant(['user_id'=>2,'site_id'=>1]);$ctx->setUser('2');self::assertNotEmpty($s->create($body,true)['id']);$this->rejects(fn()=>$s->create([...$body,'site_id'=>3],true),404);
    }
    public function testQueueKeyAndDrillAlertsDeduplicateEscalateAndResolve():void {
        [$app,$db,$ctx]=$this->fixture();$this->rule($app,$db);$s=$app->container()->make('operational_alert_service');$s->health(['site_id'=>1,'pending_count'=>2,'blocked_count'=>1,'oldest_at'=>gmdate('Y-m-d H:i:s',time()-7200)]);$asset=$app->container()->make('key_custody_service')->create(['site_id'=>1,'asset_code'=>'GATE-1','asset_name'=>'Gate','asset_type'=>'KEY'])['id'];$app->container()->make('key_custody_service')->issue($asset,['employee_id'=>2,'expected_revision'=>1,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue']);$db->execute("UPDATE custody_loans SET due_at='2020-01-01 00:00:00'");$db->execute("INSERT INTO emergency_exercises(company_id,site_id,procedure_id,exercise_type,title,state,started_by_user_id,started_at,closed_at) VALUES(101,1,1,'DRILL','Practice','CLOSED_WITH_FINDINGS',1,'2020-01-01 00:00:00','2020-01-01 01:00:00')");self::assertSame(3,$s->tick()['created']);self::assertSame(0,$s->tick()['notifications']);self::assertSame(3,(int)$db->fetch('SELECT COUNT(*) AS n FROM notifications')['n']);$db->execute("UPDATE operational_alerts SET opened_at='2020-01-01 00:00:00'");self::assertSame(3,$s->tick()['notifications']);$s->acknowledge('1',['expected_revision'=>1]);$s->health(['site_id'=>1,'pending_count'=>0,'blocked_count'=>0,'oldest_at'=>null]);$app->container()->make('key_custody_service')->manageLoan('1','cancel',['expected_revision'=>1,'notes'=>'Return deadline test cancelled']);$app->container()->make('emergency_procedure_service')->resolveFindings('1',['expected_revision'=>1,'notes'=>'Follow-up exercise completed.']);self::assertSame(3,$s->tick()['resolved']);self::assertCount(3,array_filter($s->workspace(['site_id'=>1])['alerts'],fn($a)=>$a['state']==='RESOLVED'));$s->health(['site_id'=>1,'pending_count'=>1,'blocked_count'=>1,'oldest_at'=>gmdate('Y-m-d H:i:s',time()-7200)]);self::assertSame(1,$s->tick()['created']);self::assertSame(2,(int)array_values(array_filter($s->workspace(['site_id'=>1])['alerts'],fn($a)=>$a['alert_type']==='QUEUE_PENDING'))[0]['episode']);
    }
    public function testAlertRecipientsLosingPermissionsDoNotReceiveNewNotifications():void {
        [$app,$db]=$this->fixture();$this->rule($app,$db);$db->execute("DELETE FROM role_permissions WHERE role_id=1 AND permission_id IN(SELECT permission_id FROM permissions WHERE company_id=101 AND permission_code='operational_alerts.view')");$s=$app->container()->make('operational_alert_service');$s->health(['site_id'=>1,'pending_count'=>1,'blocked_count'=>1,'oldest_at'=>gmdate('Y-m-d H:i:s',time()-3600)]);self::assertSame(0,$s->tick()['notifications']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM notifications')['n']);
    }
    public function testReleaseNoticesHaveExplicitReadReceipts():void {
        [$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('customer_support_service');$id=$s->notice(['title'=>'New inspection update','body'=>'Prepare forms before leaving coverage.','audience'=>'ALL'])['id'];$ctx->setUser('2');$notice=$s->notices()[0];$this->rejects(fn()=>$s->readNotice($id,['expected_hash'=>'bad']),409);$s->readNotice($id,['expected_hash'=>$notice['content_hash']]);$s->readNotice($id,['expected_hash'=>$notice['content_hash']]);self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM release_notice_reads')['n']);$ctx->setTenantId(202);$ctx->setUser('3');self::assertSame([],$s->notices());
    }
    public function testRestrictedAccountsCannotIssueIntegrationCredentialsOrCrossSites():void {
        [$app,$db,$ctx]=$this->fixture();$db->execute("INSERT INTO permissions VALUES(9991,101,'site_scope.restricted','ACTIVE')");$access=$app->container()->make('site_access_service');$access->restrictRole(['role_id'=>2,'restricted'=>true]);$access->grant(['user_id'=>2,'site_id'=>2]);$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$ctx->setUser('2');$auth=$app->container()->make('authorization_service');self::assertFalse($auth->isAllowed('2','integrations.manage'));self::assertTrue($auth->isAllowed('2','control_map.view'));$this->rejects(fn()=>$app->container()->make('control_map_service')->snapshot(['site_id'=>1]),404);$this->rejects(fn()=>$app->container()->make('operational_alert_service')->health(['site_id'=>1,'pending_count'=>0,'blocked_count'=>0,'oldest_at'=>null]),404);
    }
    public function testAuditFailureRollsBackIngressAndDoesNotLeaveReceipt():void {
        [$app,$db]=$this->fixture();$s=$app->container()->make('integration_centre_service');$key=$s->createKey(['site_id'=>1,'label'=>'Alarm','scopes'=>['alarms.write'],'valid_days'=>1])['api_key'];$db->execute("CREATE TRIGGER reject_hub_audit BEFORE INSERT ON audit_logs BEGIN SELECT RAISE(ABORT,'audit unavailable');END");try{$s->incoming($key,'alarms.write',['operation_uuid'=>uuid4(),'title'=>'Alarm','description'=>'Test','severity'=>'LOW']);self::fail('Expected audit failure');}catch(\PDOException){self::assertTrue(true);}self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM incidents')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM integration_receipts')['n']);
    }
}
